"<!DOCTYPE html>
<html lang=\"en\">
<head>
    <meta charset=\"UTF-8\">
    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">
    <title>Simple 3D Game</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            font-family: Arial, sans-serif;
        }
        #ui {
            position: absolute;
            top: 20px;
            left: 20px;
            color: white;
            font-size: 24px;
            font-weight: bold;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.8);
            pointer-events: none;
        }
        #game-over {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            color: #ff414d;
            font-size: 48px;
            font-weight: bold;
            display: none;
            text-align: center;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.8);
        }
    </style>
</head>
<body>

    <div id=\"ui\">Score: <span id=\"score\">0</span></div>
    <div id=\"game-over\">GAME OVER<br><span style=\"font-size:20px; color:white;\">Refresh the page to play again</span></div>

    <!-- Import Three.js via CDN -->
    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"></script>

    <script>
        // 1. SCENE, CAMERA, @COMMENT_BODY@ RENDERER SETUP
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a2e);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // 2. LIGHTING
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(20, 40, 20);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // 3. ARENA (FLOOR)
        const arenaSize = 30;
        const floorGeo = new THREE.PlaneGeometry(arenaSize, arenaSize);
        const floorMat = new THREE.MeshStandardMaterial({ color: 0x16213e });
        const floor = new THREE.Mesh(floorGeo, floorMat);
        floor.rotation.x = -Math.PI / 2;
        floor.receiveShadow = true;
        scene.add(floor);

        // 4. PLAYER SETUP
        const playerGeo = new THREE.SphereGeometry(0.8, 32, 32);
        const playerMat = new THREE.MeshStandardMaterial({ color: 0x00fff5, roughness: 0.2 });
        const player = new THREE.Mesh(playerGeo, playerMat);
        player.position.set(0, 0.8, 0);
        player.castShadow = true;
        scene.add(player);

        // 5. COLLECTIBLES @COMMENT_BODY@ OBSTACLES
        let score = 0;
        let isGameOver = false;

        // Coin (Gold Cube)
        const coinGeo = new THREE.BoxGeometry(0.8, 0.8, 0.8);
        const coinMat = new THREE.MeshStandardMaterial({ color: 0xffbd39 });
        const coin = new THREE.Mesh(coinGeo, coinMat);
        coin.castShadow = true;
        scene.add(coin);

        // Obstacles (Red Cubes)
        const obstacles = [];
        const obstacleGeo = new THREE.BoxGeometry(1.2, 1.2, 1.2);
        const obstacleMat = new THREE.MeshStandardMaterial({ color: 0xff414d });

        function spawnObstacles(count) {
            for (let i = 0; i < count; i++) {
                const obs = new THREE.Mesh(obstacleGeo, obstacleMat);
                obs.castShadow = true;
                resetPosition(obs);
                scene.add(obs);
                obstacles.push(obs);
            }
        }

        function resetPosition(mesh) {
            const limit = (arenaSize / 2) - 2;
            mesh.position.x = (Math.random() - 0.5) * 2 * limit;
            mesh.position.z = (Math.random() - 0.5) * 2 * limit;
            mesh.position.y = 0.6;
        }

        resetPosition(coin);
        spawnObstacles(8);

        // 6. CONTROLS
        const keys = {};
        const speed = 0.25;

        window.addEventListener('keydown', (e) => keys[e.key.toLowerCase()] = true);
        window.addEventListener('keyup', (e) => keys[e.key.toLowerCase()] = false);

        // 7. GAME LOOP @COMMENT_BODY@ LOGIC
        function animate() {
            if (isGameOver) return;

            requestAnimationFrame(animate);

            // Player Movement
            if (keys['w'] || keys['arrowup']) player.position.z -= speed;
            if (keys['s'] || keys['arrowdown']) player.position.z += speed;
            if (keys['a'] || keys['arrowleft']) player.position.x -= speed;
            if (keys['d'] || keys['arrowright']) player.position.x += speed;

            // Keep Player Within Arena Boundaries
            const limit = (arenaSize / 2) - 0.8;
            player.position.x = Math.max(-limit, Math.min(limit, player.position.x));
            player.position.z = Math.max(-limit, Math.min(limit, player.position.z));

            // Coin Rotation Animation
            coin.rotation.x += 0.02;
            coin.rotation.y += 0.02;

            // Camera Tracking
            camera.position.x = player.position.x;
            camera.position.z = player.position.z + 14;
            camera.position.y = player.position.y + 12;
            camera.lookAt(player.position);

            // Collision Detection: Player @COMMENT_BODY@ Coin
            if (player.position.distanceTo(coin.position) < 1.2) {
                score += 10;
                document.getElementById('score').innerText = score;
                resetPosition(coin);
            }

            // Collision Detection: Player @COMMENT_BODY@ Obstacles
            obstacles.forEach(obs => {
                if (player.position.distanceTo(obs.position) < 1.4) {
                    isGameOver = true;
                    document.getElementById('game-over').style.display = 'block';
                }
            });

            renderer.render(scene, camera);
        }

        // Handle Window Resizing
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>

