// Input and run state
const keys=Object.create(null);let score=0,lives=3,timeLeft=60,running=false,paused=false,gameEnded=false,dashCooldown=0,dashTime=0,invulnerable=0,elapsed=0,last=performance.now(),moveX=0,moveZ=0,toastTimer=0;
function setToast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),900)}
function setScore(){scoreEl.textContent=String(score).padStart(3,'0')}
function setLives(){ $('lives').textContent=Array.from({length:3},(_,i)=>i<lives?'♥':'♡').join(' ')}
function setOverlay(kind){overlay.classList.remove('hidden');if(kind==='pause'){$('eyebrow').textContent='CATCH YOUR BREATH';$('title').innerHTML='RUN<br><span>PAUSED</span>';$('message').textContent='Your run is on hold. The sentinels will wait.';$('result').hidden=true;startBtn.textContent='RESUME RUN';$('note').textContent='PRESS ESC OR TAP RESUME TO CONTINUE'}else if(kind==='over'){$('eyebrow').textContent=timeLeft<=0?'SURVIVAL COMPLETE':'RUN ENDED';$('title').innerHTML=timeLeft<=0?'YOU<br><span>MADE IT</span>':'GAME<br><span>OVER</span>';$('message').textContent=timeLeft<=0?'The arena is yours. One minute survived.':'The sentinels got you. The arena awaits another run.';$('result').hidden=false;$('result').textContent='SHARDS  '+String(score).padStart(3,'0');startBtn.textContent='PLAY AGAIN';$('note').textContent=''} }
function begin(){score=0;lives=3;timeLeft=60;running=true;paused=false;gameEnded=false;dashCooldown=0;dashTime=0;invulnerable=0;elapsed=0;player.position.set(0,.72,0);setScore();setLives();timerEl.textContent='60';for(const h of hazards){placeObject(h.group,4);h.center.x=h.group.position.x;h.center.z=h.group.position.z}for(const s of shards)placeObject(s,2);overlay.classList.add('hidden');last=performance.now()}
startBtn.addEventListener('click',()=>{if(paused){paused=false;running=true;overlay.classList.add('hidden');last=performance.now()}else begin()});$('pause').addEventListener('click',()=>{if(!running||gameEnded)return;paused=!paused;if(paused){running=false;setOverlay('pause')}else{running=true;overlay.classList.add('hidden');last=performance.now()}});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','w','a','s','d'].includes(k))e.preventDefault();keys[k]=true;if(k===' '&&!e.repeat)dash() ;if(k==='escape'&&running){running=false;paused=true;setOverlay('pause')}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{for(const k in keys)keys[k]=false;if(running){running=false;paused=true;setOverlay('pause')}});
function dash(){if(!running||dashCooldown>0)return;dashTime=.19;dashCooldown=1.35;invulnerable=Math.max(invulnerable,.3);setToast('DASH!')}
$('dash').addEventListener('pointerdown',e=>{e.preventDefault();dash()});
// Mobile virtual joystick
defineTouchPad();function defineTouchPad(){const pad=$('touchPad'),stick=$('stick');let activeId=null;const move=e=>{if(e.pointerId!==activeId)return;const r=pad.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=38,len=Math.hypot(dx,dy),scale=len>max?max/len:1;stick.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;moveX=dx*scale/max;moveZ=dy*scale/max};pad.addEventListener('pointerdown',e=>{e.preventDefault();activeId=e.pointerId;pad.setPointerCapture(activeId);move(e)});pad.addEventListener('pointermove',move);const end=e=>{if(e.pointerId!==activeId)return;activeId=null;moveX=moveZ=0;stick.style.transform=''};pad.addEventListener('pointerup',end);pad.addEventListener('pointercancel',end)}
function collect(shard){score+=10;setScore();shard.position.set(100,0,100);setToast('+10 SHARDS');setTimeout(()=>{if(running)placeObject(shard,2)},450)}
function hitHazard(h){if(invulnerable>0)return;lives--;setLives();invulnerable=1.15;player.position.x+=(player.position.x-h.group.position.x)*.42;player.position.z+=(player.position.z-h.group.position.z)*.42;if(lives<=0){running=false;gameEnded=true;setOverlay('over')}else setToast('HIT! KEEP MOVING')}
function update(dt){elapsed+=dt;timeLeft=Math.max(0,60-elapsed);timerEl.textContent=String(Math.ceil(timeLeft)).padStart(2,'0');dashCooldown=Math.max(0,dashCooldown-dt);dashTime=Math.max(0,dashTime-dt);invulnerable=Math.max(0,invulnerable-dt);
let ix=(keys.a||keys.arrowleft?-1:0)+(keys.d||keys.arrowright?1:0)+moveX,iz=(keys.w||keys.arrowup?-1:0)+(keys.s||keys.arrowdown?1:0)+moveZ;const len=Math.hypot(ix,iz);if(len>1){ix/=len;iz/=len}const speed=(dashTime>0?14:7.1)*dt;player.position.x=THREE.MathUtils.clamp(player.position.x+ix*speed,-half+.95,half-.95);player.position.z=THREE.MathUtils.clamp(player.position.z+iz*speed,-half+.95,half-.95);if(len>.05){player.rotation.y=Math.atan2(ix,iz);player.rotation.z=-ix*.12}player.position.y=.72+Math.sin(elapsed*5)*.045;player.scale.setScalar(dashTime>0?1.13:1);player.visible=invulnerable<=0||Math.floor(elapsed*15)%2===0;
for(const shard of shards){if(shard.position.x>50)continue;shard.rotation.y+=dt*1.6;shard.rotation.x=Math.sin(elapsed*1.5+shard.position.x)*.12;shard.position.y=.92+Math.sin(elapsed*2.7+shard.position.z)*.13;if(Math.hypot(player.position.x-shard.position.x,player.position.z-shard.position.z)<1.17)collect(shard)}
for(const h of hazards){h.phase+=dt*h.baseSpeed*h.turn;h.group.position.x=THREE.MathUtils.clamp(h.center.x+Math.sin(h.phase)*h.amp,-half+2,half-2);h.group.position.z=THREE.MathUtils.clamp(h.center.z+Math.cos(h.phase*.8)*h.amp,-half+2,half-2);h.group.rotation.y+=dt*.7;h.ring.rotation.z+=dt*.8;if(Math.hypot(player.position.x-h.group.position.x,player.position.z-h.group.position.z)<1.45)hitHazard(h)}
// A new sentinel enters as the run progresses.
if(elapsed>25&&!hazards[5]){const g=new THREE.Group(),core=new THREE.Mesh(hazardGeo,hazardMat),ring=new THREE.Mesh(new THREE.TorusGeometry(1.08,.035,7,32),new THREE.MeshBasicMaterial({color:0xff7691,transparent:true,opacity:.72}));ring.rotation.x=Math.PI/2;g.add(core,ring);g.position.y=.85;scene.add(g);placeObject(g,6);hazards.push({group:g,phase:0,baseSpeed:.92,amp:3.1,turn:1,center:{x:g.position.x,z:g.position.z},core,ring})}
const target=new THREE.Vector3(player.position.x,0,player.position.z);const camTarget=new THREE.Vector3(player.position.x,20,player.position.z+22);camera.position.lerp(camTarget,1-Math.exp(-dt*3.1));camera.lookAt(target);cyanLight.position.x=-12+Math.sin(elapsed*.3)*3;pinkLight.position.z=10+Math.cos(elapsed*.25)*3;
if(timeLeft<=0&&running){running=false;gameEnded=true;setOverlay('over')}}
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-last)/1000);last=now;if(running)update(dt);else{elapsed+=dt*.24;for(const s of shards)if(s.position.x<50)s.rotation.y+=dt*.4}renderer.render(scene,camera)}requestAnimationFrame(frame);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight)});
// Pause and replay keyboard shortcuts
setScore();setLives();
})();
</script>
</body>
</html>

